///////////////////////////////////////////////////////////////////////////////
// rmii_if.sv
///////////////////////////////////////////////////////////////////////////////
// SystemVerilog interface for the RMII (Reduced MII) side of the
// rmii_to_mii adapter.
//
// TX signals (driven by DUT, outputs to PHY / monitored by UVM):
//   rmii_txd[1:0], rmii_tx_en
//
// RX signals (driven by PHY / UVM driver, inputs to DUT):
//   rmii_rxd[1:0], rmii_crs_dv
//
// Clock is the 50 MHz RMII reference clock (generated by testbench).
///////////////////////////////////////////////////////////////////////////////

interface rmii_if (
  input logic rmii_ref_clk,
  input logic rst_n
);

  // TX side (DUT → PHY)
  logic [1:0] rmii_txd;
  logic       rmii_tx_en;

  // RX side (PHY → DUT)
  logic [1:0] rmii_rxd;
  logic       rmii_crs_dv;

  modport tx_monitor (input  rmii_ref_clk, rst_n,
                      input  rmii_txd, rmii_tx_en);
  modport rx_driver  (input  rmii_ref_clk, rst_n,
                      output rmii_rxd, rmii_crs_dv);

endinterface
